def balanced(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    i = 0
    n = len(s)

    while i < n:
        ch = s[i]

        if ch == '"':
            i += 1
            while i < n:
                if s[i] == '\\':
                    i += 2
                elif s[i] == '"':
                    i += 1
                    break
                else:
                    i += 1
            else:
                return False
            continue

        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()

        i += 1

    return not stack
